# Now I have a good understanding. Let me start the actual implementation.
# I'll implement in Go since that's what direnv uses.

# Let me create the main Go files
mkdir -p /workspace/src

# Start with the main.go and the key packages
cat > /workspace/src/main.go << 'EOF'
package main

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

const VERSION = "2.37.1"

func main() {
	args := os.Args[1:]
	if len(args) == 0 {
		printHelp(false)
		os.Exit(1)
	}

	cmd := args[0]
	rest := args[1:]

	switch cmd {
	case "allow", "permit", "grant":
		cmdAllow(rest)
	case "block", "deny", "disallow", "revoke":
		cmdDeny(rest)
	case "edit":
		cmdEdit(rest)
	case "exec":
		cmdExec(rest)
	case "export":
		cmdExport(rest)
	case "fetchurl":
		cmdFetchURL(rest)
	case "help":
		showPrivate := false
		if len(rest) > 0 && rest[0] != "" {
			showPrivate = true
		}
		printHelp(showPrivate)
	case "hook":
		cmdHook(rest)
	case "prune":
		cmdPrune(rest)
	case "reload":
		cmdReload(rest)
	case "status":
		cmdStatus(rest)
	case "stdlib":
		cmdStdlib(rest)
	case "version":
		cmdVersion(rest)
	case "log":
		cmdLog(rest)
	case "dump":
		cmdDump(rest)
	case "apply_dump":
		cmdApplyDump(rest)
	case "watch":
		cmdWatch(rest)
	case "watch-dir":
		cmdWatchDir(rest)
	case "dotenv":
		cmdDotenv(rest)
	case "check-required":
		cmdCheckRequired(rest)
	default:
		fmt.Fprintf(os.Stderr, "direnv: error unknown command %s\n", cmd)
		printHelp(false)
		os.Exit(1)
	}
}

func printHelp(showPrivate bool) {
	fmt.Printf("direnv v%s\n", VERSION)
	fmt.Println("Usage: direnv COMMAND [...ARGS]")
	fmt.Println("")
	fmt.Println("Available commands")
	fmt.Println("------------------")
	fmt.Printf("allow [PATH_TO_RC]:\n  aliases: permit, grant\n  Grants direnv permission to load the given .envrc or .env file.\n")
	fmt.Printf("block [PATH_TO_RC]:\n  aliases: deny, disallow, revoke\n  Revokes the authorization of a given .envrc or .env file.\n")
	fmt.Printf("edit [PATH_TO_RC]:\n  Opens PATH_TO_RC or the current .envrc or .env into an $EDITOR and allow\n  the file to be loaded afterwards.\n")
	fmt.Printf("exec DIR COMMAND [...ARGS]:\n  Executes a command after loading the first .envrc or .env found in DIR\n")
	fmt.Printf("export SHELL:\n  Loads an .envrc or .env and prints the diff in terms of exports.\n  Supported SHELL values are: [vim, systemd, fish, json, tcsh, gzenv, murex, zsh, pwsh, bash, elvish, gha]\n")
	fmt.Printf("fetchurl <url> [<integrity-hash>]:\n  Fetches a given URL into direnv's CAS\n")
	fmt.Printf("help [SHOW_PRIVATE]:\n  Shows this help\n")
	fmt.Printf("hook SHELL:\n  Used to setup the shell hook\n")
	fmt.Printf("prune:\n  Removes old allowed and required files\n")
	fmt.Printf("reload:\n  Triggers an env reload\n")
	fmt.Printf("status [--json]:\n  Prints some debug status information\n")
	fmt.Printf("stdlib:\n  Displays the stdlib available in the .envrc execution context\n")
	fmt.Printf("version [VERSION_AT_LEAST]:\n  prints the version or checks that direnv is older than VERSION_AT_LEAST.\n")
	fmt.Printf("log [--status | --error] <message>:\n  Logs a given message\n")
}

// findRC searches for .envrc or .env file starting from the given directory
func findRC(fromDir string, loadDotenv bool) string {
	dir := fromDir
	for {
		envrc := filepath.Join(dir, ".envrc")
		if _, err := os.Stat(envrc); err == nil {
			return envrc
		}
		if loadDotenv {
			dotenv := filepath.Join(dir, ".env")
			if _, err := os.Stat(dotenv); err == nil {
				return dotenv
			}
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			break
		}
		dir = parent
	}
	return ""
}

// logStatus writes a status message to stderr
func logStatus(format string, args ...interface{}) {
	msg := fmt.Sprintf(format, args...)
	fmt.Fprintf(os.Stderr, "\033[0mdirenv: %s\n", msg)
}

// logError writes an error message to stderr
func logError(format string, args ...interface{}) {
	msg := fmt.Sprintf(format, args...)
	fmt.Fprintf(os.Stderr, "\033[31mdirenv: error %s\033[0m\n", msg)
}

func selfPath() string {
	path, err := filepath.Abs(os.Args[0])
	if err != nil {
		return os.Args[0]
	}
	return path
}

func getConfigDir() string {
	if d := os.Getenv("DIRENV_CONFIG"); d != "" {
		return d
	}
	if d := os.Getenv("XDG_CONFIG_HOME"); d != "" {
		return filepath.Join(d, "direnv")
	}
	home, _ := os.UserHomeDir()
	return filepath.Join(home, ".config", "direnv")
}

func getDataDir() string {
	if d := os.Getenv("XDG_DATA_HOME"); d != "" {
		return filepath.Join(d, "direnv")
	}
	home, _ := os.UserHomeDir()
	return filepath.Join(home, ".local", "share", "direnv")
}

func escapeStringBash(s string) string {
	// Use $'...' format for bash
	if strings.ContainsAny(s, "\\'\"!") || strings.ContainsRune(s, '\n') || strings.ContainsRune(s, '\r') || strings.ContainsRune(s, '\t') {
		return "$'" + escapeSingleQuoteBytes(s) + "'"
	}
	// Use simple single-quote if no single quotes
	return "'" + s + "'"
}

func escapeSingleQuoteBytes(s string) string {
	var result strings.Builder
	for _, c := range s {
		switch c {
		case '\'':
			result.WriteString("\\'")
		case '\\':
			result.WriteString("\\\\")
		case '\n':
			result.WriteString("\\n")
		case '\r':
			result.WriteString("\\r")
		case '\t':
			result.WriteString("\\t")
		case 0:
			result.WriteString("\\0")
		default:
			result.WriteRune(c)
		}
	}
	return result.String()
}
EOF
echo "main.go created"

