// allowHash computes the hash used for the allow file
// hash = SHA256(path + "\n" + content_of_file)
func allowHash(rcPath string) (string, error) {
	content, err := os.ReadFile(rcPath)
	if err != nil {
		return "", err
	}
	h := sha256.New()
	h.Write([]byte(rcPath + "\n"))
	h.Write(content)
	return fmt.Sprintf("%x", h.Sum(nil)), nil
}

// denyHash computes the hash used for the deny file
// hash = SHA256(path + "\n")
func denyHash(rcPath string) string {
	h := sha256.New()
	h.Write([]byte(rcPath + "\n"))
	return fmt.Sprintf("%x", h.Sum(nil))
}

// AllowedStatus represents whether an RC file is allowed
type AllowedStatus int

