	}

	// Check allow file
	allowDir := filepath.Join(dataDir, "allow")
	ah, err := allowHash(rcPath)
	if err != nil {
		return AllowedStatusNotFound
	}
	allowFile := filepath.Join(allowDir, ah)
	if _, err := os.Stat(allowFile); err == nil {
		return AllowedStatusAllowed
	}

