package main

import (
	"bytes"
	"compress/zlib"
	"encoding/base64"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"time"
)

// FileWatch represents a watched file
type FileWatch struct {
	Path    string `json:"path"`
	Modtime int64  `json:"modtime"`
	Exists  bool   `json:"exists"`
}

// WatchList is a list of file watches
type WatchList []FileWatch

// encodeWatches encodes the watch list to a base64url-encoded zlib-compressed JSON string
func encodeWatches(watches WatchList) (string, error) {
	jsonData, err := json.Marshal(watches)
	if err != nil {
		return "", err
	}

	var buf bytes.Buffer
	w := zlib.NewWriter(&buf)
	_, err = w.Write(jsonData)
	if err != nil {
		return "", err
	}
	w.Close()

	return base64.URLEncoding.EncodeToString(buf.Bytes()), nil
}

// decodeWatches decodes a base64url-encoded zlib-compressed JSON watch list
func decodeWatches(s string) (WatchList, error) {
	b, err := base64.URLEncoding.DecodeString(s)
	if err != nil {
		return nil, err
	}

	r, err := zlib.NewReader(bytes.NewReader(b))
	if err != nil {
		return nil, err
	}
	defer r.Close()

	data, err := io.ReadAll(r)
	if err != nil {
		return nil, err
	}

	var watches WatchList
	if err := json.Unmarshal(data, &watches); err != nil {
		return nil, err
	}

	return watches, nil
}

// fileWatchFromPath creates a FileWatch from a file path
func fileWatchFromPath(path string) FileWatch {
	stat, err := os.Stat(path)
	if err != nil {
		return FileWatch{
			Path:    path,
			Modtime: 0,
			Exists:  false,
		}
	}
	return FileWatch{
		Path:    path,
		Modtime: stat.ModTime().Unix(),
		Exists:  true,
	}
}

// makeRCWatches creates the initial watch list for an RC file
// It includes the RC file, the allow file, and the deny file
func makeRCWatches(rcPath string) WatchList {
	watches := WatchList{
		fileWatchFromPath(rcPath),
	}

	allowPath := rcAllowPath(rcPath)
	if allowPath != "" {
		watches = append(watches, fileWatchFromPath(allowPath))
	}

	denyPath := rcDenyPath(rcPath)
	watches = append(watches, fileWatchFromPath(denyPath))

	return watches
}

// mergeWatches merges new watches with existing ones
func mergeWatches(existing WatchList, newPaths []string) WatchList {
	// Build a map of existing watches by path
	watchMap := make(map[string]FileWatch)
	var order []string
	for _, w := range existing {
		if _, ok := watchMap[w.Path]; !ok {
			order = append(order, w.Path)
		}
		watchMap[w.Path] = w
	}

	// Add new paths
	for _, path := range newPaths {
		absPath, err := filepath.Abs(path)
		if err != nil {
			absPath = path
		}
		if _, ok := watchMap[absPath]; !ok {
			order = append(order, absPath)
		}
		watchMap[absPath] = fileWatchFromPath(absPath)
	}

	result := make(WatchList, 0, len(order))
	for _, path := range order {
		result = append(result, watchMap[path])
	}
	return result
}

// watchesHaveChanged checks if any watched files have changed
func watchesHaveChanged(watches WatchList) bool {
	for _, w := range watches {
		stat, err := os.Stat(w.Path)
		if err != nil {
			if w.Exists {
				return true // file was deleted
			}
			continue
		}
		if !w.Exists {
			return true // file appeared
		}
		if stat.ModTime().Unix() != w.Modtime {
			return true
		}
	}
	return false
}

func cmdWatch(args []string) {
	if len(args) < 2 {
		logError("usage: direnv watch <shell> <path>...")
		os.Exit(1)
	}

	shell := args[0]
	paths := args[1:]

	// Get existing watches from env
	existing := getEnvWatches()

	// Merge with new paths
	merged := mergeWatches(existing, paths)

	// Encode and output
	encoded, err := encodeWatches(merged)
	if err != nil {
		logError("failed to encode watches: %s", err)
		os.Exit(1)
	}

	fmt.Print(exportVar(shell, "DIRENV_WATCHES", encoded))
}

func cmdWatchDir(args []string) {
	if len(args) < 2 {
		logError("usage: direnv watch-dir <shell> <path>")
		os.Exit(1)
	}

	shell := args[0]
	dirPath := args[1]

	absDir, err := filepath.Abs(dirPath)
	if err != nil {
		absDir = dirPath
	}

	// Get existing watches
	existing := getEnvWatches()

	// Add dir and all its contents recursively
	var paths []string
	paths = append(paths, absDir)
	filepath.Walk(absDir, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return nil
		}
		paths = append(paths, path)
		return nil
	})

	merged := mergeWatches(existing, paths)

	encoded, err := encodeWatches(merged)
	if err != nil {
		logError("failed to encode watches: %s", err)
		os.Exit(1)
	}

	fmt.Print(exportVar(shell, "DIRENV_WATCHES", encoded))
}

func getEnvWatches() WatchList {
	s := os.Getenv("DIRENV_WATCHES")
	if s == "" {
		return nil
	}
	watches, err := decodeWatches(s)
	if err != nil {
		return nil
	}
	return watches
}

func watchListToStatus(watches WatchList, rcDir string) []string {
	var lines []string
	for _, w := range watches {
		// Try to make path relative to rcDir
		rel, err := filepath.Rel(rcDir, w.Path)
		if err != nil {
			rel = w.Path
		}
		t := time.Unix(w.Modtime, 0).UTC().Format("2006-01-02T15:04:05Z")
		lines = append(lines, fmt.Sprintf("Found watch: %q - %s", rel, t))
	}
	return lines
}
