package main

import (
	"bytes"
	"compress/zlib"
	"encoding/base64"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"sort"
	"strings"
)

// EnvMap is a map of environment variables
type EnvMap map[string]string

// EnvDiff represents the diff between two environments
type EnvDiff struct {
	Prev EnvMap `json:"p"`
	Next EnvMap `json:"n"`
}

// encodeEnvDiff encodes an EnvDiff to a base64url-encoded zlib-compressed JSON string
func encodeEnvDiff(diff EnvDiff) (string, error) {
	jsonData, err := json.Marshal(diff)
	if err != nil {
		return "", err
	}

	var buf bytes.Buffer
	w := zlib.NewWriter(&buf)
	_, err = w.Write(jsonData)
	if err != nil {
		return "", err
	}
	w.Close()

	return base64.URLEncoding.EncodeToString(buf.Bytes()), nil
}

// decodeEnvDiff decodes a base64url-encoded zlib-compressed JSON EnvDiff
func decodeEnvDiff(s string) (EnvDiff, error) {
	b, err := base64.URLEncoding.DecodeString(s)
	if err != nil {
		return EnvDiff{}, err
	}

	r, err := zlib.NewReader(bytes.NewReader(b))
	if err != nil {
		return EnvDiff{}, err
	}
	defer r.Close()

	data, err := io.ReadAll(r)
	if err != nil {
		return EnvDiff{}, err
	}

	var diff EnvDiff
	if err := json.Unmarshal(data, &diff); err != nil {
		return EnvDiff{}, err
	}

	if diff.Prev == nil {
		diff.Prev = EnvMap{}
	}
	if diff.Next == nil {
		diff.Next = EnvMap{}
	}

	return diff, nil
}

// getCurrentEnv returns the current environment as a map
func getCurrentEnv() EnvMap {
	env := make(EnvMap)
	for _, e := range os.Environ() {
		parts := strings.SplitN(e, "=", 2)
		if len(parts) == 2 {
			env[parts[0]] = parts[1]
		} else {
			env[parts[0]] = ""
		}
	}
	return env
}

// computeBaseEnv computes the base environment (before direnv) by reversing the diff
func computeBaseEnv(currentEnv EnvMap, diff EnvDiff) EnvMap {
	base := make(EnvMap)
	for k, v := range currentEnv {
		base[k] = v
	}

	// Remove vars that were added by the previous diff
	for k := range diff.Next {
		delete(base, k)
	}

	// Add back vars that were in the previous environment
	for k, v := range diff.Prev {
		base[k] = v
	}

	return base
}

// computeNewDiff computes a new diff between base env and the new loaded env
func computeNewDiff(baseEnv EnvMap, newEnv EnvMap) EnvDiff {
	prev := make(EnvMap)
	next := make(EnvMap)

	// Find vars in newEnv that differ from baseEnv
	for k, v := range newEnv {
		// Skip DIRENV_IN_ENVRC
		if k == "DIRENV_IN_ENVRC" {
			continue
		}
		if bv, ok := baseEnv[k]; !ok || bv != v {
			next[k] = v
			if ok {
				prev[k] = bv
			}
		}
	}

	// Find vars in baseEnv that are missing from newEnv (were unset)
	for k, v := range baseEnv {
		if k == "DIRENV_IN_ENVRC" {
			continue
		}
		if _, ok := newEnv[k]; !ok {
			// This var was removed - but we don't track removals in next directly
			// We only track what needs to be added
			// But we do need to know what was previously there
			_ = v
		}
	}

	return EnvDiff{Prev: prev, Next: next}
}

// gzenvEncode encodes an environment map to gzenv format (zlib(json))
func gzenvEncode(env EnvMap) (string, error) {
	jsonData, err := json.Marshal(env)
	if err != nil {
		return "", err
	}

	var buf bytes.Buffer
	w := zlib.NewWriter(&buf)
	_, err = w.Write(jsonData)
	if err != nil {
		return "", err
	}
	w.Close()

	return base64.URLEncoding.EncodeToString(buf.Bytes()), nil
}

// gzenvDecode decodes a gzenv string to an environment map
func gzenvDecode(s string) (EnvMap, error) {
	b, err := base64.URLEncoding.DecodeString(s)
	if err != nil {
		return nil, fmt.Errorf("base64 decoding: %s", err)
	}

	r, err := zlib.NewReader(bytes.NewReader(b))
	if err != nil {
		return nil, fmt.Errorf("zlib decompressing: %s", err)
	}
	defer r.Close()

	data, err := io.ReadAll(r)
	if err != nil {
		return nil, fmt.Errorf("reading: %s", err)
	}

	var env EnvMap
	if err := json.Unmarshal(data, &env); err != nil {
		return nil, fmt.Errorf("json unmarshal: %s", err)
	}

	return env, nil
}

// sortedKeys returns sorted keys of an EnvMap
func sortedKeys(m EnvMap) []string {
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	return keys
}

// cmdDump outputs the current environment in various formats
func cmdDump(args []string) {
	format := "gzenv"
	if len(args) > 0 {
		format = args[0]
	}

	env := getCurrentEnv()

	// Remove DIRENV_IN_ENVRC from dump
	delete(env, "DIRENV_IN_ENVRC")

	// Check if there's a dump file path set
	dumpFilePath := os.Getenv("DIRENV_DUMP_FILE_PATH")

	switch format {
	case "gzenv", "":
		encoded, err := gzenvEncode(env)
		if err != nil {
			logError("failed to encode env: %s", err)
			os.Exit(1)
		}
		if dumpFilePath != "" {
			os.WriteFile(dumpFilePath, []byte(encoded+"\n"), 0644)
		} else {
			fmt.Println(encoded)
		}
	case "json":
		data, err := json.MarshalIndent(env, "", "  ")
		if err != nil {
			logError("failed to marshal env: %s", err)
			os.Exit(1)
		}
		if dumpFilePath != "" {
			os.WriteFile(dumpFilePath, data, 0644)
		} else {
			fmt.Println(string(data))
		}
	case "bash":
		var sb strings.Builder
		for _, k := range sortedKeys(env) {
			v := env[k]
			sb.WriteString("export ")
			sb.WriteString(k)
			sb.WriteString("=")
			sb.WriteString(escapeStringBash(v))
			sb.WriteString(";")
		}
		if dumpFilePath != "" {
			os.WriteFile(dumpFilePath, []byte(sb.String()), 0644)
		} else {
			fmt.Print(sb.String())
		}
	default:
		// Just use bash format
		var sb strings.Builder
		for _, k := range sortedKeys(env) {
			v := env[k]
			sb.WriteString("export ")
			sb.WriteString(k)
			sb.WriteString("=")
			sb.WriteString(escapeStringBash(v))
			sb.WriteString(";")
		}
		if dumpFilePath != "" {
			os.WriteFile(dumpFilePath, []byte(sb.String()), 0644)
		} else {
			fmt.Print(sb.String())
		}
	}
}

// cmdApplyDump applies a dump file (converts to shell exports)
func cmdApplyDump(args []string) {
	if len(args) == 0 {
		logError("not enough arguments")
		os.Exit(1)
	}

	filePath := args[0]
	data, err := os.ReadFile(filePath)
	if err != nil {
		logError("failed to read dump file: %s", err)
		os.Exit(1)
	}

	content := strings.TrimRight(string(data), "\n")

	// Try to decode as gzenv
	newEnv, err := gzenvDecode(content)
	if err != nil {
		logError("unmarshal() %s", err)
		os.Exit(1)
	}

	// Get current env
	currentEnv := getCurrentEnv()

	// Compute what to set and what to unset
	var sb strings.Builder

	// Set new vars
	for k, v := range newEnv {
		if k == "DIRENV_IN_ENVRC" {
			continue
		}
		if cv, ok := currentEnv[k]; !ok || cv != v {
			sb.WriteString("export ")
			sb.WriteString(k)
			sb.WriteString("=")
			sb.WriteString(escapeStringBash(v))
			sb.WriteString(";")
		}
	}

	// Unset vars that are in current but not in new
	for k := range currentEnv {
		if k == "DIRENV_IN_ENVRC" {
			continue
		}
		if _, ok := newEnv[k]; !ok {
			sb.WriteString("unset ")
			sb.WriteString(k)
			sb.WriteString(";")
		}
	}

	fmt.Print(sb.String())
}
