		return fmt.Sprintf("${env:%s}=%s;", key, pwshQuote(value))
	case "vim":
		return fmt.Sprintf("call setenv(%s,%s)\n", vimQuote(key), vimQuote(value))
	case "gha":
		return fmt.Sprintf("%s<<%s\n%s\n%s\n", key, ghaDelimiter(value), value, ghaDelimiter(value))
	case "systemd":
		return fmt.Sprintf("%s=%s\n", key, value)
	case "murex", "json":
		// handled separately
		return ""
	default:
		return fmt.Sprintf("export %s=%s;", key, escapeBashValue(value))
	}
}

// unsetVar outputs a variable unset command in the given shell format
func unsetVar(shell, key string) string {
	switch shell {
	case "bash", "zsh":
		return fmt.Sprintf("unset %s;", key)
	case "fish":
		return fmt.Sprintf("set -e %s;", fishQuote(key))
	case "tcsh":
		return fmt.Sprintf("unsetenv %s ;", key)
	case "elvish":
		return fmt.Sprintf("unset-env %s\n", key)
	case "pwsh":
		return fmt.Sprintf("Remove-Item Env:\\%s;", key)
	case "vim":
		return fmt.Sprintf("call setenv(%s,v:null)\n", vimQuote(key))
	case "gha", "systemd":
		// Can't easily unset in these formats
		return ""
	default:
		return fmt.Sprintf("unset %s;", key)
	}
}

func escapeBashValue(s string) string {
	if s == "" {
		return "''"
	}
	// Check if we need to use $'...' format
	needsEscape := false
	for _, c := range s {
		if c < 32 || c == '\'' || c == '\\' {
			needsEscape = true
			break
		}
	}
	if !needsEscape {
		// Check for other shell-special chars
		if strings.ContainsAny(s, "$`\"!") {
			needsEscape = true
		}
	}
	if needsEscape {
		return "$'" + escapeSingleQuoteBytes(s) + "'"
	}
	return "'" + s + "'"
}

func fishQuote(s string) string {
	return "'" + strings.ReplaceAll(strings.ReplaceAll(s, "\\", "\\\\"), "'", "\\'") + "'"
}

func tcshQuote(s string) string {
	// For tcsh, we need special handling for the '=' sign in value
	return s
}

func elvishQuote(s string) string {
	// Elvish uses single quotes
	return "'" + strings.ReplaceAll(s, "'", "''") + "'"
}

func pwshQuote(s string) string {
	// PowerShell single-quoted string
	return "'" + strings.ReplaceAll(s, "'", "''") + "'"
}

func vimQuote(s string) string {
	// Vim string quoting with single quotes
	return "'" + strings.ReplaceAll(s, "'", "''") + "'"
}

func ghaDelimiter(value string) string {
	// Generate a unique delimiter that doesn't appear in the value
	// Based on hash of the value
	import_hash := fmt.Sprintf("%x", hashString(value))[:16]
	return fmt.Sprintf("ghadelimiter_%s", import_hash)
}

func hashString(s string) uint64 {
	var h uint64 = 14695981039346656037
	for _, c := range []byte(s) {
		h ^= uint64(c)
		h *= 1099511628211
	}
	return h
}

// cmdExport handles the 'export' command
func cmdExport(args []string) {
	if len(args) == 0 {
		logError("missing shell name")
		printHelp(false)
		os.Exit(1)
	}

	shell := args[0]

	// Validate shell
	validShells := map[string]bool{
		"bash": true, "zsh": true, "fish": true, "tcsh": true,
		"elvish": true, "pwsh": true, "vim": true, "json": true,
		"gha": true, "gzenv": true, "systemd": true, "murex": true,
	}
	if !validShells[shell] {
		logError("unknown shell %s", shell)
		os.Exit(1)
	}

	currentEnv := getCurrentEnv()

	// Find the RC file
	cwd, err := os.Getwd()
	if err != nil {
		logError("couldn't get current dir: %s", err)
		os.Exit(1)
	}

	// Get previous diff info
	prevDiffStr := currentEnv["DIRENV_DIFF"]
	var prevDiff EnvDiff
	if prevDiffStr != "" {
		prevDiff, err = decodeEnvDiff(prevDiffStr)
		if err != nil {
			prevDiff = EnvDiff{Prev: EnvMap{}, Next: EnvMap{}}
		}
	} else {
		prevDiff = EnvDiff{Prev: EnvMap{}, Next: EnvMap{}}
	}

	// Find the RC file
	loadDotenv := false // from config
	rcPath := findRC(cwd, loadDotenv)

	// Check if we're in the loaded dir still
	loadedDir := currentEnv["DIRENV_DIR"]
	if loadedDir != "" && strings.HasPrefix(loadedDir, "-") {
		loadedDirPath := loadedDir[1:]
		if rcPath == "" || !isSubdirOrEqual(cwd, loadedDirPath) {
			// We've left the loaded directory, unload
			outputUnload(shell, currentEnv, prevDiff)
			return
		}
	}

	if rcPath == "" {
		// No RC file found
		// If we were loaded, unload
		if loadedDir != "" {
			outputUnload(shell, currentEnv, prevDiff)
		}
		return
	}

	// Get the allow status
	status := rcAllowStatus(rcPath)

	// Build watches
	watches := makeRCWatches(rcPath)

	// Get existing watches from env and merge
	existingWatches := getEnvWatches()
	if existingWatches != nil {
		// Only keep watches from current RC
		// Actually, recreate from scratch for the current RC
	}
	_ = existingWatches

	if status == AllowedStatusNotFound {
		// Not allowed, not denied - print error
		watchesEncoded, _ := encodeWatches(watches)

		// Create the "empty" diff (just DIRENV_* vars for watching)
		newEnvVars := EnvMap{
			"DIRENV_DIR":     "-" + filepath.Dir(rcPath),
			"DIRENV_FILE":    rcPath,
			"DIRENV_WATCHES": watchesEncoded,
		}

		newDiff := EnvDiff{Prev: prevDiff.Next, Next: newEnvVars}
		diffEncoded, _ := encodeEnvDiff(newDiff)
		newEnvVars["DIRENV_DIFF"] = diffEncoded

		// Recompute with correct diff
		newDiff2 := EnvDiff{Prev: prevDiff.Next, Next: newEnvVars}
		diffEncoded2, _ := encodeEnvDiff(newDiff2)
		newEnvVars["DIRENV_DIFF"] = diffEncoded2

		// Output the DIRENV_* vars
		baseEnv := computeBaseEnv(currentEnv, prevDiff)
		outputDiff(shell, currentEnv, baseEnv, newEnvVars)

		logError("%s is blocked. Run `direnv allow` to approve its content", rcPath)
		os.Exit(1)
	}

	if status == AllowedStatusDenied {
		// Explicitly denied - no error, just set DIRENV_* vars
		watchesEncoded, _ := encodeWatches(watches)

		newEnvVars := EnvMap{
			"DIRENV_DIR":     "-" + filepath.Dir(rcPath),
			"DIRENV_FILE":    rcPath,
			"DIRENV_WATCHES": watchesEncoded,
		}

		newDiff := EnvDiff{Prev: prevDiff.Next, Next: newEnvVars}
		diffEncoded, _ := encodeEnvDiff(newDiff)
		newEnvVars["DIRENV_DIFF"] = diffEncoded

		newDiff2 := EnvDiff{Prev: prevDiff.Next, Next: newEnvVars}
		diffEncoded2, _ := encodeEnvDiff(newDiff2)
		newEnvVars["DIRENV_DIFF"] = diffEncoded2

		baseEnv := computeBaseEnv(currentEnv, prevDiff)
		outputDiff(shell, currentEnv, baseEnv, newEnvVars)
		return
	}

	// Allowed! Load the RC file
	rcDir := filepath.Dir(rcPath)

	// Run bash with stdlib and envrc, capture the new environment
	newEnv, err := loadRC(rcPath, rcDir, currentEnv)
	if err != nil {
		logError("%s", err)
		os.Exit(1)
	}

	// Remove DIRENV_IN_ENVRC from new env (it's set by stdlib but should be filtered)
	delete(newEnv, "DIRENV_IN_ENVRC")

	// Get the watches from the loaded env (stdlib may have added more)
	newWatches := watches
	if ws := newEnv["DIRENV_WATCHES"]; ws != "" {
		if decoded, err := decodeWatches(ws); err == nil {
			newWatches = decoded
		}
	}
	delete(newEnv, "DIRENV_WATCHES")

	watchesEncoded, _ := encodeWatches(newWatches)
	newEnv["DIRENV_WATCHES"] = watchesEncoded
	newEnv["DIRENV_DIR"] = "-" + rcDir
	newEnv["DIRENV_FILE"] = rcPath

	// Compute the diff from base env
	baseEnv := computeBaseEnv(currentEnv, prevDiff)

	newDiff := computeDiff(baseEnv, newEnv)
	diffEncoded, _ := encodeEnvDiff(newDiff)
	newEnv["DIRENV_DIFF"] = diffEncoded

	// Recompute newDiff with DIRENV_DIFF included
	newDiff2 := computeDiff(baseEnv, newEnv)
	diffEncoded2, _ := encodeEnvDiff(newDiff2)
	newEnv["DIRENV_DIFF"] = diffEncoded2

	// Output the diff
	logStatus("loading %s", rcPath)

	// Log exported vars
	logExportedVars(baseEnv, newEnv)

	outputDiff(shell, currentEnv, baseEnv, newEnv)
}

// computeDiff computes what to set/unset to go from baseEnv to newEnv
// Only tracks DIRENV-managed variables
func computeDiff(baseEnv, newEnv EnvMap) EnvDiff {
	prev := make(EnvMap)
	next := make(EnvMap)

	for k, v := range newEnv {
		if k == "DIRENV_IN_ENVRC" {
			continue
		}
		if bv, ok := baseEnv[k]; !ok || bv != v {
			next[k] = v
			if ok {
				prev[k] = bv
			}
		}
	}

	return EnvDiff{Prev: prev, Next: next}
}

// outputUnload outputs commands to unload the current direnv environment
func outputUnload(shell string, currentEnv EnvMap, prevDiff EnvDiff) {
	logStatus("unloading")

	// Unset all variables that were set by direnv (they're in prevDiff.Next)
	if shell == "json" {
		env := make(EnvMap)
		for k, v := range prevDiff.Prev {
			env[k] = v
		}
		data, _ := json.Marshal(env)
		fmt.Println(string(data))
		return
	}

	if shell == "murex" || shell == "elvish" {
		// JSON format for murex/elvish
		env := make(EnvMap)
		for k, v := range prevDiff.Prev {
			env[k] = v
		}
		data, _ := json.Marshal(env)
		fmt.Println(string(data))
		return
	}

	var sb strings.Builder

	keys := sortedKeys(prevDiff.Next)
	// Sort for consistent output, but use the actual keys order
	_ = keys

	for _, k := range keysOf(prevDiff.Next) {
		if v, ok := prevDiff.Prev[k]; ok {
			sb.WriteString(exportVar(shell, k, v))
		} else {
			sb.WriteString(unsetVar(shell, k))
		}
	}

	if sb.Len() > 0 {
		fmt.Print(sb.String())
	}
}

func keysOf(m EnvMap) []string {
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	return keys
}

// outputDiff outputs the diff between currentEnv and the target newEnv
func outputDiff(shell string, currentEnv, baseEnv, newEnv EnvMap) {
	if shell == "json" {
		// Output all new env vars minus what's in base that hasn't changed
		result := make(EnvMap)
		for k, v := range newEnv {
			if k == "DIRENV_IN_ENVRC" {
				continue
			}
			result[k] = v
		}
		data, _ := json.MarshalIndent(result, "", "  ")
		fmt.Println(string(data))
		return
	}

	if shell == "gzenv" {
		encoded, err := gzenvEncode(newEnv)
		if err != nil {
			logError("failed to encode: %s", err)
			os.Exit(1)
		}
		fmt.Println(encoded)
		return
	}

	if shell == "murex" {
		// murex uses JSON format
		result := make(EnvMap)
		for k, v := range newEnv {
			if k == "DIRENV_IN_ENVRC" {
				continue
			}
			result[k] = v
		}
		// Also add nulls for unset vars
		_ = baseEnv
		data, _ := json.Marshal(result)
		fmt.Println(string(data))
		return
	}

	if shell == "elvish" {
		// elvish uses JSON format  
		result := make(EnvMap)
		for k, v := range newEnv {
			if k == "DIRENV_IN_ENVRC" {
				continue
			}
			result[k] = v
		}
		data, _ := json.Marshal(result)
		fmt.Println(string(data))
		return
	}

	var sb strings.Builder

	// Output vars to set/update (in newEnv but different from currentEnv)
	for k, v := range newEnv {
		if k == "DIRENV_IN_ENVRC" {
			continue
		}
		if cv, ok := currentEnv[k]; !ok || cv != v {
			sb.WriteString(exportVar(shell, k, v))
		}
	}

	// Output vars to unset (in prevDiff.Next but not in newEnv)
	// We need to figure out what was previously loaded and is now gone
	// By looking at what's in the current env but was set by direnv
	prevDiffStr := currentEnv["DIRENV_DIFF"]
	if prevDiffStr != "" {
		prevDiff, err := decodeEnvDiff(prevDiffStr)
		if err == nil {
			for k := range prevDiff.Next {
				if _, ok := newEnv[k]; !ok {
					sb.WriteString(unsetVar(shell, k))
				}
			}
		}
	}

	if sb.Len() > 0 {
		fmt.Print(sb.String())
	}
}

func logExportedVars(baseEnv, newEnv EnvMap) {
	var added, changed, removed []string

	for k := range newEnv {
		if k == "DIRENV_DIFF" || k == "DIRENV_DIR" || k == "DIRENV_FILE" || k == "DIRENV_WATCHES" || k == "DIRENV_IN_ENVRC" {
			continue
		}
		if _, ok := baseEnv[k]; !ok {
			added = append(added, k)
		} else if baseEnv[k] != newEnv[k] {
			changed = append(changed, k)
		}
	}

	// Check for removed vars
	// (vars in base that were set by direnv are now gone)
	_ = removed

	if len(added) > 0 || len(changed) > 0 {
		sort.Strings(added)
		sort.Strings(changed)

		var parts []string
		for _, k := range added {
			parts = append(parts, "+"+k)
		}
		for _, k := range changed {
			parts = append(parts, "~"+k)
		}

		logStatus("export %s", strings.Join(parts, " "))
	}
}

func isSubdirOrEqual(path, dir string) bool {
	if path == dir {
		return true
	}
	if strings.HasPrefix(path, dir+"/") {
		return true
	}
	return false
}

func filepath_Dir(p string) string {
	// Just to avoid "import path/filepath" issue
	return p
}

// tcshExport outputs tcsh-compatible exports
func tcshExport(envVars EnvMap, currentEnv EnvMap, prevDiffStr string) string {
	var sb strings.Builder

	for k, v := range envVars {
		if k == "DIRENV_IN_ENVRC" {
			continue
		}
		// tcsh uses setenv with space-separated value
		// Values with '=' need special quoting
		escapedV := v
		// Remove = sign in tcsh value: just pass raw but wrap in quotes if needed
		if strings.ContainsAny(v, " \t\n") {
			escapedV = fmt.Sprintf(`"%s"`, strings.ReplaceAll(v, `"`, `\"`))
		}
		sb.WriteString(fmt.Sprintf("setenv %s %s ;", k, escapedV))
	}

	if prevDiffStr != "" {
		prevDiff, err := decodeEnvDiff(prevDiffStr)
		if err == nil {
			for k := range prevDiff.Next {
				if _, ok := envVars[k]; !ok {
					sb.WriteString(fmt.Sprintf("unsetenv %s ;", k))
				}
			}
		}
	}

	return sb.String()
}
