// loadRC loads an RC file using bash and returns the resulting environment
func loadRC(rcPath, rcDir string, currentEnv EnvMap) (EnvMap, error) {
	// Get bash path
	bashPath := getBashPath()

	// Get stdlib
	stdlib := getStdlib()

