	tmpFile.Close()

	// Run bash
	cmd := exec.Command(bashPath, tmpFile.Name())
	cmd.Env = envSlice
	cmd.Dir = rcDir
	cmd.Stderr = os.Stderr

	// Capture stdout (which is the env dump)
	output, err := cmd.Output()

