// cmdExec executes a command in the environment of the given directory
func cmdExec(args []string) {
	if len(args) < 2 {
		logError("usage: direnv exec <dir> <command> [args...]")
		os.Exit(1)
	}

	dir := args[0]
	command := args[1:]

	// Resolve the directory
	absDir, err := filepath.Abs(dir)
	if err != nil {
		logError("failed to resolve directory: %s", err)
		os.Exit(1)
	}

