	var envSlice []string
	for k, v := range targetEnv {
		if k == "DIRENV_IN_ENVRC" {
			continue
		}
		envSlice = append(envSlice, k+"="+v)
	}

	// Execute the command
	cmdPath, err := exec.LookPath(command[0])
	if err != nil {
		cmdPath = command[0]
	}

	cmd := exec.Command(cmdPath, command[1:]...)
	cmd.Env = envSlice
	cmd.Dir = absDir
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr

	if err := cmd.Run(); err != nil {
		if exitErr, ok := err.(*exec.ExitError); ok {
			os.Exit(exitErr.ExitCode())
		}
		os.Exit(1)
	}
}

// cmdReload reloads the current .envrc
func cmdReload(args []string) {
	cwd, err := os.Getwd()
	if err != nil {
		logError("couldn't get current dir: %s", err)
		os.Exit(1)
	}

	rcPath := findRC(cwd, false)
	if rcPath == "" {
		logError(".envrc not found")
		os.Exit(1)
	}

	// Touch the RC file to force a reload
	now := time.Now()
	os.Chtimes(rcPath, now, now)
}
