package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

// parseDotenv parses a .env file and returns a map of key=value pairs
// It handles:
// - Lines starting with # are comments
// - KEY=value format
// - KEY="value" format (double quoted, no expansion)
// - KEY='value' format (single quoted, no expansion)
// - Lines starting with 'export ' prefix are stripped
func parseDotenv(path string) ([]string, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer f.Close()

	var pairs []string
	scanner := bufio.NewScanner(f)
	lineNum := 0

	for scanner.Scan() {
		lineNum++
		line := scanner.Text()

		// Skip empty lines
		if strings.TrimSpace(line) == "" {
			continue
		}

		// Skip comments
		if strings.HasPrefix(strings.TrimSpace(line), "#") {
			continue
		}

		// Strip 'export ' prefix
		line = strings.TrimSpace(line)
		if strings.HasPrefix(line, "export ") {
			line = strings.TrimSpace(line[7:])
		}

		// Find the = sign
		eqIdx := strings.IndexByte(line, '=')
		if eqIdx < 0 {
			return nil, fmt.Errorf("invalid line: %s", line)
		}

		key := line[:eqIdx]
		rawValue := line[eqIdx+1:]

		// Validate key
		if key == "" {
			return nil, fmt.Errorf("invalid line: %s", line)
		}
		for _, c := range key {
			if !isValidKeyChar(c) {
				return nil, fmt.Errorf("invalid line: %s", line)
			}
		}

		// Parse value
		value, err := parseDotenvValue(rawValue)
		if err != nil {
			return nil, fmt.Errorf("invalid line: %s", line)
		}

		pairs = append(pairs, key+"="+value)
	}

	return pairs, scanner.Err()
}

func isValidKeyChar(c rune) bool {
	return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_'
}

// parseDotenvValue parses the value part of a dotenv line
func parseDotenvValue(s string) (string, error) {
	if s == "" {
		return "", nil
	}

	// Double-quoted value
	if strings.HasPrefix(s, "\"") {
		// Find closing quote - handles escapes
		var result strings.Builder
		i := 1
		for i < len(s) {
			c := s[i]
			if c == '"' {
				i++
				break
			}
			if c == '\\' && i+1 < len(s) {
				i++
				switch s[i] {
				case 'n':
					result.WriteByte('\n')
				case 't':
					result.WriteByte('\t')
				case 'r':
					result.WriteByte('\r')
				case '"':
					result.WriteByte('"')
				case '\\':
					result.WriteByte('\\')
				case '$':
					result.WriteByte('$')
				default:
					result.WriteByte('\\')
					result.WriteByte(s[i])
				}
			} else if c == '$' && i+1 < len(s) {
				// Variable expansion - skip for simplicity
				// Find var name
				i++
				if s[i] == '{' {
					// ${VAR} - skip to }
					end := strings.IndexByte(s[i:], '}')
					if end >= 0 {
						varName := s[i+1 : i+end]
						result.WriteString(os.Getenv(varName))
						i += end + 1
					}
				} else {
					// $VAR
					start := i
					for i < len(s) && (isAlphaNum(rune(s[i])) || s[i] == '_') {
						i++
					}
					varName := s[start:i]
					result.WriteString(os.Getenv(varName))
				}
				continue
			} else {
				result.WriteByte(c)
			}
			i++
		}
		return result.String(), nil
	}

	// Single-quoted value  
	if strings.HasPrefix(s, "'") {
		end := strings.Index(s[1:], "'")
		if end < 0 {
			return s[1:], nil
		}
		return s[1 : end+1], nil
	}

	// Unquoted value - handle $ expansion
	var result strings.Builder
	i := 0
	for i < len(s) {
		c := s[i]
		if c == '#' {
			// Comment starts here
			break
		}
		if c == '$' && i+1 < len(s) {
			i++
			if s[i] == '{' {
				// ${VAR}
				end := strings.IndexByte(s[i:], '}')
				if end >= 0 {
					varName := s[i+1 : i+end]
					result.WriteString(os.Getenv(varName))
					i += end + 1
				}
			} else {
				// $VAR
				start := i
				for i < len(s) && (isAlphaNum(rune(s[i])) || s[i] == '_') {
					i++
				}
				varName := s[start:i]
				result.WriteString(os.Getenv(varName))
			}
			continue
		}
		result.WriteByte(c)
		i++
	}
	return strings.TrimSpace(result.String()), nil
}

func isAlphaNum(c rune) bool {
	return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9')
}

// cmdDotenv handles the dotenv command
func cmdDotenv(args []string) {
	if len(args) == 0 {
		logError("usage: direnv dotenv <shell> [<path>]")
		os.Exit(1)
	}

	shell := args[0]
	path := ""
	if len(args) > 1 {
		path = args[1]
	}

	if path == "" {
		cwd, err := os.Getwd()
		if err != nil {
			logError("couldn't get current dir: %s", err)
			os.Exit(1)
		}
		path = cwd + "/.env"
	}

	// Check if it's a directory
	stat, err := os.Stat(path)
	if err != nil {
		logError("open %s: %s", path, err)
		os.Exit(1)
	}
	if stat.IsDir() {
		path = path + "/.env"
	}

	pairs, err := parseDotenv(path)
	if err != nil {
		logError("%s", err)
		os.Exit(1)
	}

	if shell == "json" {
		m := make(map[string]string)
		for _, p := range pairs {
			eqIdx := strings.IndexByte(p, '=')
			if eqIdx >= 0 {
				m[p[:eqIdx]] = p[eqIdx+1:]
			}
		}

		// Output as JSON
		out := "{\n"
		keys := make([]string, 0, len(m))
		for k := range m {
			keys = append(keys, k)
		}
		// Sort keys
		for i := 0; i < len(keys)-1; i++ {
			for j := i + 1; j < len(keys); j++ {
				if keys[i] > keys[j] {
					keys[i], keys[j] = keys[j], keys[i]
				}
			}
		}
		for i, k := range keys {
			if i > 0 {
				out += ",\n"
			}
			out += fmt.Sprintf("  %q: %q", k, m[k])
		}
		out += "\n}\n"
		fmt.Print(out)
		return
	}

	// Output shell export commands
	var sb strings.Builder
	for _, p := range pairs {
		eqIdx := strings.IndexByte(p, '=')
		if eqIdx >= 0 {
			k := p[:eqIdx]
			v := p[eqIdx+1:]
			sb.WriteString(exportVar(shell, k, v))
		}
	}
	if sb.Len() > 0 {
		fmt.Print(sb.String())
	}
}
