package main

import (
	"crypto/sha256"
	"encoding/base64"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"strings"
)

// cmdFetchURL handles the fetchurl command
func cmdFetchURL(args []string) {
	if len(args) == 0 {
		logError("missing URL argument")
		os.Exit(1)
	}

	url := args[0]
	var integrityHash string
	if len(args) > 1 {
		integrityHash = args[1]
	}

	// Fetch the URL
	resp, err := http.Get(url)
	if err != nil {
		logError("failed to fetch URL: %s", err)
		os.Exit(1)
	}
	defer resp.Body.Close()

	content, err := io.ReadAll(resp.Body)
	if err != nil {
		logError("failed to read response: %s", err)
		os.Exit(1)
	}

	// Compute SHA256 hash
	h := sha256.Sum256(content)
	hashBytes := base64.URLEncoding.EncodeToString(h[:])
	// Remove padding
	hashBytes = strings.TrimRight(hashBytes, "=")
	computedHash := "sha256-" + hashBytes

	if integrityHash == "" {
		// Just report the hash
		isTTY := isTerminal(os.Stdout.Fd())
		if isTTY {
			fmt.Printf("Found hash: %s\n\nInvoke fetchurl again with the hash as an argument to get the disk location:\n\n  direnv fetchurl %q %q\n  #=> %s\n",
				computedHash, url, computedHash, casPath(computedHash))
		} else {
			fmt.Println(computedHash)
		}
		return
	}

	// Verify integrity
	if !hashesMatch(integrityHash, computedHash, content) {
		logError("integrity check failed: expected %s, got %s", integrityHash, computedHash)
		os.Exit(1)
	}

	// Store in CAS
	casDir := getCASDir()
	if err := os.MkdirAll(casDir, 0755); err != nil {
		logError("failed to create CAS dir: %s", err)
		os.Exit(1)
	}

	// Normalize the hash for the filename
