package main

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

// varsToIgnore is the set of environment variables that direnv never exports
var varsToIgnore = map[string]bool{
	"SHLVL":            true,
	"_":                true,
	"PWD":              true,
	"OLDPWD":           true,
	"DIRENV_IN_ENVRC":  true,
}

// exportVar outputs a variable assignment in the given shell format
func exportVar(shell, key, value string) string {
	switch shell {
	case "bash", "zsh":
		return fmt.Sprintf("export %s=%s;", key, escapeBashValue(value))
	case "fish":
		return fmt.Sprintf("set -x -g %s %s;", fishQuote(key), fishQuote(value))
	case "tcsh":
		return fmt.Sprintf("setenv %s %s ;", key, tcshValue(value))
	case "elvish":
		// handled in outputDiff
		return ""
	case "pwsh":
		return fmt.Sprintf("${env:%s}=%s;", key, pwshQuote(value))
	case "vim":
		return fmt.Sprintf("call setenv(%s,%s)\n", vimQuote(key), vimQuote(value))
	case "gha":
		delim := ghaDelimiter(key + value)
		return fmt.Sprintf("%s<<%s\n%s\n%s\n", key, delim, value, delim)
	case "systemd":
		return fmt.Sprintf("%s=%s\n", key, value)
	default:
		return fmt.Sprintf("export %s=%s;", key, escapeBashValue(value))
	}
}

// unsetVar outputs a variable unset command in the given shell format
func unsetVar(shell, key string) string {
	switch shell {
	case "bash", "zsh":
		return fmt.Sprintf("unset %s;", key)
	case "fish":
		return fmt.Sprintf("set -e %s;", fishQuote(key))
	case "tcsh":
		return fmt.Sprintf("unsetenv %s ;", key)
	case "elvish":
		// handled in outputDiff
		return ""
	case "pwsh":
		return fmt.Sprintf("[System.Environment]::SetEnvironmentVariable('%s',[NullString]::Value,'Process');", key)
	case "vim":
		return fmt.Sprintf("call setenv(%s,v:null)\n", vimQuote(key))
	case "gha", "systemd":
		return ""
	default:
		return fmt.Sprintf("unset %s;", key)
	}
}

func escapeBashValue(s string) string {
	if s == "" {
		return "''"
	}
	// Check if we need to use $'...' format
	needsEscape := false
	for _, c := range s {
		if c < 32 || c == '\'' || c == '\\' {
			needsEscape = true
			break
		}
	}
	if !needsEscape {
		if strings.ContainsAny(s, "$`\"!") {
			needsEscape = true
		}
	}
	if needsEscape {
