	for _, c := range s {
		switch c {
		case '\'':
			result.WriteString("\\'")
		case '\\':
			result.WriteString("\\\\")
		default:
			result.WriteRune(c)
		}
	}
	result.WriteByte('\'')
	return result.String()
}

func tcshValue(s string) string {
	// tcsh: if value contains spaces, wrap in quotes
	if strings.ContainsAny(s, " \t\n") {
		return "\"" + strings.ReplaceAll(s, "\"", "\\\"") + "\""
	}
	return s
}

