// cmdExport handles the 'export' command
func cmdExport(args []string) {
	if len(args) == 0 {
		logError("missing shell name")
		printHelp(false)
		os.Exit(1)
	}

	shell := args[0]

	// Validate shell
	validShells := map[string]bool{
		"bash": true, "zsh": true, "fish": true, "tcsh": true,
		"elvish": true, "pwsh": true, "vim": true, "json": true,
		"gha": true, "gzenv": true, "systemd": true, "murex": true,
	}
	if !validShells[shell] {
		logError("unknown shell %s", shell)
		os.Exit(1)
	}

	currentEnv := getCurrentEnv()

	// Find the RC file
	cwd, err := os.Getwd()
	if err != nil {
		logError("couldn't get current dir: %s", err)
		os.Exit(1)
	}

	// Get previous diff info
	prevDiffStr := currentEnv["DIRENV_DIFF"]
	var prevDiff EnvDiff
	if prevDiffStr != "" {
		prevDiff, err = decodeEnvDiff(prevDiffStr)
		if err != nil {
			prevDiff = EnvDiff{Prev: EnvMap{}, Next: EnvMap{}}
		}
	} else {
		prevDiff = EnvDiff{Prev: EnvMap{}, Next: EnvMap{}}
	}

	// Compute base environment (what the env looked like before direnv loaded anything)
	baseEnv := computeBaseEnv(currentEnv, prevDiff)

	// Find the RC file
	loadDotenv := false
	rcPath := findRC(cwd, loadDotenv)

	// Check if we're in the loaded dir still
	loadedDir := currentEnv["DIRENV_DIR"]
	if loadedDir != "" && strings.HasPrefix(loadedDir, "-") {
		loadedDirPath := loadedDir[1:]
		if rcPath == "" || !isSubdirOrEqual(cwd, loadedDirPath) {
			// We've left the loaded directory, unload
			outputUnload(shell, prevDiff)
			return
		}
	}

	if rcPath == "" {
		// No RC file found
		if loadedDir != "" {
			outputUnload(shell, prevDiff)
		}
		return
	}

	// Get the allow status
	status := rcAllowStatus(rcPath)

	// Build watches
	watches := makeRCWatches(rcPath)
	watchesEncoded, _ := encodeWatches(watches)

	// Build the "metadata only" env vars (DIRENV_DIR, FILE, WATCHES)
	rcDir := filepath.Dir(rcPath)
	metaEnv := EnvMap{
		"DIRENV_DIR":     "-" + rcDir,
		"DIRENV_FILE":    rcPath,
		"DIRENV_WATCHES": watchesEncoded,
	}

	if status == AllowedStatusNotFound {
		// Not allowed - print error and set metadata vars
		metaDiff := computeDiff(baseEnv, metaEnv)
		metaEnv["DIRENV_DIFF"] = encodeDiffSafe(metaDiff)
		// Recompute with diff included
		metaDiff2 := computeDiff(baseEnv, metaEnv)
		metaEnv["DIRENV_DIFF"] = encodeDiffSafe(metaDiff2)

		outputExport(shell, currentEnv, baseEnv, metaEnv, prevDiff, false)
		logError("%s is blocked. Run `direnv allow` to approve its content", rcPath)
		os.Exit(1)
	}

	if status == AllowedStatusDenied {
		// Explicitly denied
		metaDiff := computeDiff(baseEnv, metaEnv)
		metaEnv["DIRENV_DIFF"] = encodeDiffSafe(metaDiff)
		metaDiff2 := computeDiff(baseEnv, metaEnv)
		metaEnv["DIRENV_DIFF"] = encodeDiffSafe(metaDiff2)

		outputExport(shell, currentEnv, baseEnv, metaEnv, prevDiff, false)
		return
	}

	// Allowed! Load the RC file
	newEnv, err := loadRC(rcPath, rcDir, baseEnv, currentEnv)
	if err != nil {
		logError("%s", err)
		os.Exit(1)
	}

	// Remove excluded vars from newEnv
	for k := range varsToIgnore {
		delete(newEnv, k)
	}

	// Get watches from the loaded env (stdlib may have added more via watch_file)
	if ws := newEnv["DIRENV_WATCHES"]; ws != "" {
		// Keep the watches from the loaded env
		watchesEncoded = ws
	}
	delete(newEnv, "DIRENV_WATCHES")

	// Set metadata
	newEnv["DIRENV_WATCHES"] = watchesEncoded
	newEnv["DIRENV_DIR"] = "-" + rcDir
	newEnv["DIRENV_FILE"] = rcPath

	// Compute the diff
	newDiff := computeDiff(baseEnv, newEnv)
	newEnv["DIRENV_DIFF"] = encodeDiffSafe(newDiff)
	// Recompute with diff included
	newDiff2 := computeDiff(baseEnv, newEnv)
	newEnv["DIRENV_DIFF"] = encodeDiffSafe(newDiff2)

	// Log what we're doing
	logStatus("loading %s", rcPath)
	logExportedVars(baseEnv, newEnv)

	outputExport(shell, currentEnv, baseEnv, newEnv, prevDiff, true)
}

func encodeDiffSafe(diff EnvDiff) string {
	encoded, err := encodeEnvDiff(diff)
	if err != nil {
		return ""
	}
	return encoded
}

// computeBaseEnv computes what the environment looked like before direnv modified it
func computeBaseEnv(currentEnv EnvMap, prevDiff EnvDiff) EnvMap {
	base := make(EnvMap)
	for k, v := range currentEnv {
		base[k] = v
	}

	// Remove vars that were added by the previous direnv load
	for k := range prevDiff.Next {
		delete(base, k)
	}

	// Restore vars that were there before the previous direnv load
	for k, v := range prevDiff.Prev {
		base[k] = v
	}

	return base
}

// computeDiff computes what's different between baseEnv and newEnv
func computeDiff(baseEnv, newEnv EnvMap) EnvDiff {
	prev := make(EnvMap)
	next := make(EnvMap)

	for k, v := range newEnv {
		// Skip vars we never track
		if varsToIgnore[k] {
			continue
		}
		if bv, ok := baseEnv[k]; !ok || bv != v {
			next[k] = v
			if ok {
				prev[k] = bv
			}
		}
	}

	return EnvDiff{Prev: prev, Next: next}
}

// outputUnload outputs commands to unload the current direnv environment
func outputUnload(shell string, prevDiff EnvDiff) {
	logStatus("unloading")

	if shell == "json" {
		// Output the base vars that should be restored
		result := make(EnvMap)
		for k, v := range prevDiff.Prev {
			result[k] = v
		}
		// Add null entries for vars to unset
		_ = prevDiff.Next
		data, _ := json.MarshalIndent(result, "", "  ")
		fmt.Println(string(data))
		return
	}

	if shell == "murex" || shell == "elvish" {
		result := make(EnvMap)
		for k, v := range prevDiff.Prev {
			result[k] = v
		}
		// Mark deleted vars as null in murex/elvish
		unloadMurexElvish(shell, prevDiff)
		return
	}

	if shell == "gzenv" {
		// Can't easily "unload" in gzenv format, just encode an empty map
		encoded, _ := gzenvEncode(EnvMap{})
		fmt.Println(encoded)
		return
	}

	var sb strings.Builder
	for _, k := range keysOf(prevDiff.Next) {
		if v, ok := prevDiff.Prev[k]; ok {
			sb.WriteString(exportVar(shell, k, v))
		} else {
			sb.WriteString(unsetVar(shell, k))
		}
	}

	if sb.Len() > 0 {
		fmt.Print(sb.String())
	}
}

func unloadMurexElvish(shell string, prevDiff EnvDiff) {
	result := make(map[string]interface{})
	for k, v := range prevDiff.Prev {
		result[k] = v
	}
	for k := range prevDiff.Next {
		if _, ok := prevDiff.Prev[k]; !ok {
			result[k] = nil
		}
	}
	data, _ := json.Marshal(result)
	fmt.Println(string(data))
}

// outputExport outputs the actual export commands
func outputExport(shell string, currentEnv, baseEnv, newEnv EnvMap, prevDiff EnvDiff, loaded bool) {
	if shell == "json" {
		// Output vars that differ from current env
		result := make(EnvMap)
		for k, v := range newEnv {
			if varsToIgnore[k] {
				continue
			}
			result[k] = v
		}
		data, _ := json.MarshalIndent(result, "", "  ")
		fmt.Println(string(data))
		return
	}

	if shell == "gzenv" {
		filtered := make(EnvMap)
		for k, v := range newEnv {
			if !varsToIgnore[k] {
				filtered[k] = v
			}
		}
		encoded, err := gzenvEncode(filtered)
		if err != nil {
			logError("failed to encode: %s", err)
			os.Exit(1)
		}
		fmt.Println(encoded)
		return
	}

	if shell == "murex" || shell == "elvish" {
		result := make(map[string]interface{})
		for k, v := range newEnv {
			if varsToIgnore[k] {
				continue
			}
			if cv, ok := currentEnv[k]; !ok || cv != v {
				result[k] = v
			}
		}
		// Mark deleted vars as null
		for k := range prevDiff.Next {
			if _, ok := newEnv[k]; !ok {
				result[k] = nil
			}
		}
		data, _ := json.Marshal(result)
		fmt.Println(string(data))
		return
	}

	var sb strings.Builder

	// Output vars to set/update
	for k, v := range newEnv {
		if varsToIgnore[k] {
			continue
		}
		if cv, ok := currentEnv[k]; !ok || cv != v {
			if shell == "elvish" {
				sb.WriteString(fmt.Sprintf("set-env %s %s\n", k, elvishQuote(v)))
			} else {
				sb.WriteString(exportVar(shell, k, v))
			}
		}
	}

	// Unset vars that were in previous diff but are not in new env
	for k := range prevDiff.Next {
		if _, ok := newEnv[k]; !ok {
			if shell == "elvish" {
				sb.WriteString(fmt.Sprintf("unset-env %s\n", k))
			} else {
				sb.WriteString(unsetVar(shell, k))
			}
		}
	}

	if sb.Len() > 0 {
		fmt.Print(sb.String())
	}
}

func elvishQuote(s string) string {
	return "'" + strings.ReplaceAll(s, "'", "''") + "'"
}

func logExportedVars(baseEnv, newEnv EnvMap) {
	var added, changed, removed []string

	for k := range newEnv {
		if k == "DIRENV_DIFF" || k == "DIRENV_DIR" || k == "DIRENV_FILE" || k == "DIRENV_WATCHES" || varsToIgnore[k] {
			continue
		}
		if _, ok := baseEnv[k]; !ok {
			added = append(added, k)
		} else if baseEnv[k] != newEnv[k] {
			changed = append(changed, k)
		}
	}

	// Check for removed vars (in base but not in new, except DIRENV_* and ignored)
	for k := range baseEnv {
		if strings.HasPrefix(k, "DIRENV_") || varsToIgnore[k] {
			continue
		}
		if _, ok := newEnv[k]; !ok {
			removed = append(removed, k)
		}
	}

	if len(added) > 0 || len(changed) > 0 || len(removed) > 0 {
		sort.Strings(added)
		sort.Strings(changed)
		sort.Strings(removed)

		var parts []string
		for _, k := range added {
			parts = append(parts, "+"+k)
		}
		for _, k := range changed {
			parts = append(parts, "~"+k)
		}
		for _, k := range removed {
			parts = append(parts, "-"+k)
		}

		logStatus("export %s", strings.Join(parts, " "))
	}
}

func isSubdirOrEqual(path, dir string) bool {
	if path == dir {
		return true
	}
	if strings.HasPrefix(path, dir+"/") {
		return true
	}
	return false
}

func keysOf(m EnvMap) []string {
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	return keys
}
