// loadRC loads an RC file using bash and returns the resulting environment
// It receives the baseEnv (env before any direnv vars) and currentEnv (actual current env)
func loadRC(rcPath, rcDir string, baseEnv EnvMap, currentEnv EnvMap) (EnvMap, error) {
	// Get bash path
	bashPath := getBashPath()

	// Get stdlib content
	stdlib := getStdlib()

	// Replace the direnv path in stdlib
	self := selfPath()
	stdlib = strings.Replace(stdlib, `direnv="/workspace/executable"`, fmt.Sprintf(`direnv="%s"`, self), 1)

	// Get config dir
	configDir := getConfigDir()

	// Build the script content
	scriptContent := stdlib
	scriptContent += "\n__main__ source \"" + shellEscapeArg(rcPath) + "\"\n"

	// Build the environment to pass to bash
	// Pass base_env (what the user had before direnv) plus DIRENV_CONFIG
	envMap := make(EnvMap)
	for k, v := range baseEnv {
		// Skip vars that bash will change itself
		if k == "SHLVL" || k == "_" || k == "OLDPWD" {
			continue
		}
		envMap[k] = v
	}
	// Add DIRENV config
	envMap["DIRENV_CONFIG"] = configDir

	// Convert env map to []string
	var envSlice []string
	for k, v := range envMap {
		envSlice = append(envSlice, k+"="+v)
	}

	// Write script to temp file
	tmpFile, err := os.CreateTemp("", "direnv-*.sh")
	if err != nil {
		return nil, fmt.Errorf("failed to create temp file: %s", err)
	}
	defer os.Remove(tmpFile.Name())

	tmpFile.WriteString(scriptContent)
	tmpFile.Close()

	// Run bash
	cmd := exec.Command(bashPath, tmpFile.Name())
	cmd.Env = envSlice
	cmd.Dir = rcDir
	cmd.Stderr = os.Stderr

	// Capture stdout (which is the env dump via fd 3)
	output, err := cmd.Output()

	if err != nil {
		if exitErr, ok := err.(*exec.ExitError); ok {
			return nil, fmt.Errorf(".envrc exec failed: %s", exitErr)
		}
		return nil, fmt.Errorf("failed to run bash: %s", err)
	}

	// Parse the output - it's JSON format from `direnv dump json ""`
	outputStr := strings.TrimRight(string(output), "\n")
	if outputStr == "" {
		return make(EnvMap), nil
	}

	var newEnv EnvMap
	if err := json.Unmarshal([]byte(outputStr), &newEnv); err != nil {
		return nil, fmt.Errorf("failed to parse env dump: %s (output: %s)", err, outputStr[:min(100, len(outputStr))])
	}

	return newEnv, nil
}

// shellEscapeArg escapes a string for use as a shell argument in double quotes
func shellEscapeArg(s string) string {
	return strings.ReplaceAll(strings.ReplaceAll(s, "\\", "\\\\"), "\"", "\\\"")
}

// getBashPath returns the path to bash
func getBashPath() string {
	if path, err := exec.LookPath("bash"); err == nil {
		return path
	}
	return "/bin/bash"
}

// warnTimeout returns the configured warn timeout
func warnTimeout() time.Duration {
	envVal := os.Getenv("DIRENV_WARN_TIMEOUT")
	if envVal == "" {
		return 5 * time.Second
	}
	d, err := time.ParseDuration(envVal)
	if err != nil {
		return 5 * time.Second
	}
	return d
}

// cmdEdit opens the RC file in the editor and allows it
func cmdEdit(args []string) {
	var rcPath string
	if len(args) > 0 {
		rcPath = args[0]
	}

	var rc string
	var err error
	if rcPath == "" {
		cwd, _ := os.Getwd()
		rc = findRC(cwd, false)
		if rc == "" {
			rc = filepath.Join(cwd, ".envrc")
		}
	} else {
		rc, err = resolveRCPath(rcPath)
		if err != nil {
			rc, _ = filepath.Abs(rcPath)
		}
	}

	editor := os.Getenv("EDITOR")
	if editor == "" {
		editor = os.Getenv("VISUAL")
	}
	if editor == "" {
		editor = "vi"
	}

	// Get mod time before editing
	var beforeMtime int64
	if stat, err := os.Stat(rc); err == nil {
		beforeMtime = stat.ModTime().UnixNano()
	}

	// Open editor
	cmd := exec.Command("sh", "-c", editor+" "+shellEscapeArg(rc))
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	cmd.Run()

	// Check if file was modified
	if stat, err := os.Stat(rc); err == nil {
		if stat.ModTime().UnixNano() != beforeMtime {
			cmdAllow([]string{rc})
		}
	}
}

// cmdExec executes a command in the environment of the given directory
func cmdExec(args []string) {
	if len(args) < 2 {
		logError("usage: direnv exec <dir> <command> [args...]")
		os.Exit(1)
	}

	dir := args[0]
	command := args[1:]

	// Resolve the directory
	absDir, err := filepath.Abs(dir)
	if err != nil {
		logError("failed to resolve directory: %s", err)
		os.Exit(1)
	}

	// Find RC in the directory
	rcPath := findRC(absDir, false)

	currentEnv := getCurrentEnv()
	var targetEnv EnvMap

	if rcPath != "" {
		status := rcAllowStatus(rcPath)
		if status == AllowedStatusAllowed {
			rcDir := filepath.Dir(rcPath)
			newEnv, err := loadRC(rcPath, rcDir, currentEnv, currentEnv)
			if err != nil {
				logError("%s", err)
				os.Exit(1)
			}
			targetEnv = newEnv
			logStatus("loading %s", rcPath)
		} else {
			targetEnv = currentEnv
		}
	} else {
		targetEnv = currentEnv
	}

	// Remove excluded vars from targetEnv
	for k := range varsToIgnore {
		delete(targetEnv, k)
	}

	// Build env slice
	var envSlice []string
	for k, v := range targetEnv {
		envSlice = append(envSlice, k+"="+v)
	}

	// Execute the command
	cmdPath, err := exec.LookPath(command[0])
	if err != nil {
		cmdPath = command[0]
	}

	cmd := exec.Command(cmdPath, command[1:]...)
	cmd.Env = envSlice
	cmd.Dir = absDir
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr

	if err := cmd.Run(); err != nil {
		if exitErr, ok := err.(*exec.ExitError); ok {
			os.Exit(exitErr.ExitCode())
		}
		os.Exit(1)
	}
}

// cmdReload reloads the current .envrc
func cmdReload(args []string) {
	cwd, err := os.Getwd()
	if err != nil {
		logError("couldn't get current dir: %s", err)
		os.Exit(1)
	}

	rcPath := findRC(cwd, false)
	if rcPath == "" {
		logError(".envrc not found")
		os.Exit(1)
	}

	// Touch the RC file to force a reload
	now := time.Now()
	os.Chtimes(rcPath, now, now)
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}
