def compare_json_export(cwd, env):
    """Compare json exports, ignoring DIRENV_DIFF and DIRENV_WATCHES"""
    orig = subprocess.run(['/workspace/executable', 'export', 'json'],
                         capture_output=True, text=True, cwd=cwd, env=env)
    mine = subprocess.run(['/tmp/direnv_test', 'export', 'json'],
                         capture_output=True, text=True, cwd=cwd, env=env)

    if orig.returncode != mine.returncode:
        return False, f"Exit code: orig={orig.returncode}, mine={mine.returncode}"

    import json
    try:
        orig_data = json.loads(orig.stdout)
        mine_data = json.loads(mine.stdout)
    except Exception as e:
        return False, f"Parse error: {e}"

    # Remove DIRENV_DIFF and DIRENV_WATCHES
    for d in [orig_data, mine_data]:
        d.pop('DIRENV_DIFF', None)
        d.pop('DIRENV_WATCHES', None)

    if orig_data != mine_data:
        # Find differences
        all_keys = set(orig_data.keys()) | set(mine_data.keys())
        diffs = []
        for k in sorted(all_keys):
            if orig_data.get(k) != mine_data.get(k):
                diffs.append(f"{k}: orig={orig_data.get(k)[:30] if orig_data.get(k) else 'MISSING'}, mine={mine_data.get(k)[:30] if mine_data.get(k) else 'MISSING'}")
        return False, '\n'.join(diffs)

    return True, None

env = {'HOME': os.environ.get('HOME'), 'PATH': os.environ.get('PATH')}
result, msg = compare_json_export('/tmp/testenv', env)
