package main

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

// varsToIgnore is the set of environment variables that direnv never exports
var varsToIgnore = map[string]bool{
	"SHLVL":           true,
	"_":               true,
	"PWD":             true,
	"OLDPWD":          true,
	"DIRENV_IN_ENVRC": true,
}

// exportVar outputs a variable assignment in the given shell format
func exportVar(shell, key, value string) string {
	switch shell {
	case "bash", "zsh":
		return fmt.Sprintf("export %s=%s;", key, escapeBashValue(value))
	case "fish":
		return fmt.Sprintf("set -x -g %s %s;", fishQuote(key), fishQuote(value))
	case "tcsh":
		return fmt.Sprintf("setenv %s %s ;", key, tcshValue(value))
	case "pwsh":
		return fmt.Sprintf("${env:%s}=%s;", key, pwshQuote(value))
	case "vim":
		return fmt.Sprintf("call setenv(%s,%s)\n", vimQuote(key), vimQuote(value))
	case "gha":
		delim := ghaDelimiter(key + value)
		return fmt.Sprintf("%s<<%s\n%s\n%s\n", key, delim, value, delim)
	case "systemd":
		return fmt.Sprintf("%s=%s\n", key, value)
	default:
		return fmt.Sprintf("export %s=%s;", key, escapeBashValue(value))
	}
}

// unsetVar outputs a variable unset command in the given shell format
func unsetVar(shell, key string) string {
	switch shell {
	case "bash", "zsh":
		return fmt.Sprintf("unset %s;", key)
	case "fish":
		return fmt.Sprintf("set -e %s;", fishQuote(key))
	case "tcsh":
		return fmt.Sprintf("unsetenv %s ;", key)
	case "pwsh":
		return fmt.Sprintf("[System.Environment]::SetEnvironmentVariable('%s',[NullString]::Value,'Process');", key)
	case "vim":
		return fmt.Sprintf("call setenv(%s,v:null)\n", vimQuote(key))
	case "gha", "systemd":
		return ""
	default:
		return fmt.Sprintf("unset %s;", key)
	}
}

func escapeBashValue(s string) string {
	if s == "" {
		return "''"
	}
	// Check if value is a "raw number" (-?[0-9.]+)
	if isRawNumber(s) {
		return s
	}
	// Use $'...' format for all other values
	return "$'" + escapeSingleQuoteBytes(s) + "'"
}

// isRawNumber returns true if the value should be output raw (unquoted) in bash
// The pattern is: optional leading minus, followed by only digits and dots
func isRawNumber(s string) bool {
	if s == "" || s == "-" || s == "." {
		return false
	}
	i := 0
	if i < len(s) && s[i] == '-' {
		i++
	}
	if i >= len(s) {
		return false
	}
	for ; i < len(s); i++ {
		if s[i] != '.' && (s[i] < '0' || s[i] > '9') {
			return false
		}
	}
	return true
}

func fishQuote(s string) string {
	var result strings.Builder
	result.WriteByte('\'')
	for _, c := range s {
		switch c {
		case '\'':
			result.WriteString("\\'")
		case '\\':
			result.WriteString("\\\\")
		default:
			result.WriteRune(c)
		}
	}
	result.WriteByte('\'')
	return result.String()
}

func tcshValue(s string) string {
	// tcsh: if value contains spaces, wrap in quotes
	if strings.ContainsAny(s, " \t\n") {
		return "\"" + strings.ReplaceAll(s, "\"", "\\\"") + "\""
	}
	return s
}

func pwshQuote(s string) string {
	return "'" + strings.ReplaceAll(s, "'", "''") + "'"
}

func vimQuote(s string) string {
	return "'" + strings.ReplaceAll(s, "'", "''") + "'"
}

func ghaDelimiter(key string) string {
	h := hashString(key)
	return fmt.Sprintf("ghadelimiter_%016x", h)
}

func hashString(s string) uint64 {
	var h uint64 = 14695981039346656037
	for _, c := range []byte(s) {
		h ^= uint64(c)
		h *= 1099511628211
	}
	return h
}

// cmdExport handles the 'export' command
func cmdExport(args []string) {
	if len(args) == 0 {
		logError("missing shell name")
		printHelp(false)
		os.Exit(1)
	}

	shell := args[0]

	validShells := map[string]bool{
		"bash": true, "zsh": true, "fish": true, "tcsh": true,
		"elvish": true, "pwsh": true, "vim": true, "json": true,
		"gha": true, "gzenv": true, "systemd": true, "murex": true,
	}
	if !validShells[shell] {
		logError("unknown shell %s", shell)
		os.Exit(1)
	}

	currentEnv := getCurrentEnv()

	cwd, err := os.Getwd()
	if err != nil {
		logError("couldn't get current dir: %s", err)
		os.Exit(1)
	}

	// Get previous diff info
	prevDiffStr := currentEnv["DIRENV_DIFF"]
	var prevDiff EnvDiff
	if prevDiffStr != "" {
		prevDiff, err = decodeEnvDiff(prevDiffStr)
		if err != nil {
			prevDiff = EnvDiff{Prev: EnvMap{}, Next: EnvMap{}}
		}
	} else {
		prevDiff = EnvDiff{Prev: EnvMap{}, Next: EnvMap{}}
	}

	// Compute base environment (what env looked like before direnv)
	baseEnv := computeBaseEnv(currentEnv, prevDiff)

	// Find the RC file
	rcPath := findRC(cwd, false)

	// Check if we need to unload
	loadedDir := currentEnv["DIRENV_DIR"]
	if loadedDir != "" && strings.HasPrefix(loadedDir, "-") {
		loadedDirPath := loadedDir[1:]
		if rcPath == "" || !isSubdirOrEqual(cwd, loadedDirPath) {
			// Unload
			outputUnload(shell, currentEnv, baseEnv, prevDiff)
			return
		}
	}

	if rcPath == "" {
		if loadedDir != "" {
			outputUnload(shell, currentEnv, baseEnv, prevDiff)
		}
		return
	}

	// Get the allow status
	status := rcAllowStatus(rcPath)

	// Build watches
	watches := makeRCWatches(rcPath)
	watchesEncoded, _ := encodeWatches(watches)

	rcDir := filepath.Dir(rcPath)
	metaEnv := EnvMap{
		"DIRENV_DIR":     "-" + rcDir,
		"DIRENV_FILE":    rcPath,
		"DIRENV_WATCHES": watchesEncoded,
	}

	if status == AllowedStatusNotFound {
		// Not allowed
		metaDiff := computeDiff(baseEnv, metaEnv)
		metaEnv["DIRENV_DIFF"] = encodeDiffSafe(metaDiff)
		metaDiff2 := computeDiff(baseEnv, metaEnv)
		metaEnv["DIRENV_DIFF"] = encodeDiffSafe(metaDiff2)

		outputLoad(shell, currentEnv, prevDiff, metaEnv)
		logError("%s is blocked. Run `direnv allow` to approve its content", rcPath)
		os.Exit(1)
	}

	if status == AllowedStatusDenied {
		// Denied
		metaDiff := computeDiff(baseEnv, metaEnv)
		metaEnv["DIRENV_DIFF"] = encodeDiffSafe(metaDiff)
		metaDiff2 := computeDiff(baseEnv, metaEnv)
		metaEnv["DIRENV_DIFF"] = encodeDiffSafe(metaDiff2)

		outputLoad(shell, currentEnv, prevDiff, metaEnv)
		return
	}

	// Allowed - load the RC file
	newEnv, err := loadRC(rcPath, rcDir, baseEnv, currentEnv)
	if err != nil {
		logError("%s", err)
		os.Exit(1)
	}

	// Remove excluded vars
	for k := range varsToIgnore {
		delete(newEnv, k)
	}

	// Get watches from loaded env (watch_file may have added more)
	if ws := newEnv["DIRENV_WATCHES"]; ws != "" {
		watchesEncoded = ws
	}
	delete(newEnv, "DIRENV_WATCHES")

	// Set metadata
	newEnv["DIRENV_WATCHES"] = watchesEncoded
	newEnv["DIRENV_DIR"] = "-" + rcDir
	newEnv["DIRENV_FILE"] = rcPath

	// Compute diff
	newDiff := computeDiff(baseEnv, newEnv)
	newEnv["DIRENV_DIFF"] = encodeDiffSafe(newDiff)
	newDiff2 := computeDiff(baseEnv, newEnv)
	newEnv["DIRENV_DIFF"] = encodeDiffSafe(newDiff2)

	logStatus("loading %s", rcPath)
	logExportedVars(baseEnv, newEnv)

	outputLoad(shell, currentEnv, prevDiff, newEnv)
}

func encodeDiffSafe(diff EnvDiff) string {
	encoded, err := encodeEnvDiff(diff)
	if err != nil {
		return ""
	}
	return encoded
}

// computeBaseEnv computes what the environment looked like before direnv modified it
func computeBaseEnv(currentEnv EnvMap, prevDiff EnvDiff) EnvMap {
	base := make(EnvMap)
	for k, v := range currentEnv {
		base[k] = v
	}
	for k := range prevDiff.Next {
		delete(base, k)
	}
	for k, v := range prevDiff.Prev {
		base[k] = v
	}
	return base
}

// computeDiff computes what's different between baseEnv and newEnv
func computeDiff(baseEnv, newEnv EnvMap) EnvDiff {
	prev := make(EnvMap)
	next := make(EnvMap)

	for k, v := range newEnv {
		if varsToIgnore[k] {
			continue
		}
		if bv, ok := baseEnv[k]; !ok || bv != v {
			next[k] = v
