func computeBaseEnv(currentEnv EnvMap, prevDiff EnvDiff) EnvMap {
	base := make(EnvMap)
	for k, v := range currentEnv {
		base[k] = v
	}
	for k := range prevDiff.Next {
		delete(base, k)
	}
	for k, v := range prevDiff.Prev {
		base[k] = v
	}
	return base
}

// computeDiff computes what's different between baseEnv and newEnv
func computeDiff(baseEnv, newEnv EnvMap) EnvDiff {
	prev := make(EnvMap)
	next := make(EnvMap)

	for k, v := range newEnv {
		if varsToIgnore[k] {
			continue
		}
		if bv, ok := baseEnv[k]; !ok || bv != v {
			next[k] = v
			if ok {
				prev[k] = bv
			}
		}
	}

	return EnvDiff{Prev: prev, Next: next}
}

// outputLoad outputs commands to set the new environment
// newEnv contains all vars that should be active after this load
func outputLoad(shell string, currentEnv EnvMap, prevDiff EnvDiff, newEnv EnvMap) {
	// What needs to change from currentEnv to newEnv:
	// 1. Set vars that are in newEnv but not in currentEnv or have different values
	// 2. Unset vars that were in prevDiff.Next but are not in newEnv

	toSet := make(EnvMap)
	for k, v := range newEnv {
		if varsToIgnore[k] {
			continue
		}
		if cv, ok := currentEnv[k]; !ok || cv != v {
			toSet[k] = v
		}
	}

