		result := make(map[string]interface{})
		for k, v := range toSet {
			result[k] = v
		}
		for _, k := range toUnset {
			result[k] = nil
		}
		data, _ := json.MarshalIndent(result, "", "  ")
		fmt.Println(string(data))
		return
	}

	if shell == "gzenv" {
		// For gzenv, include all new env vars
		filtered := make(EnvMap)
		for k, v := range newEnv {
			if !varsToIgnore[k] {
				filtered[k] = v
			}
		}
