		// Also add back the base vars that haven't changed
		// (gzenv needs the full env for apply_dump)
		encoded, err := gzenvEncode(filtered)
		if err != nil {
			logError("failed to encode: %s", err)
			os.Exit(1)
		}
		fmt.Println(encoded)
		return
	}

	if shell == "murex" || shell == "elvish" {
		result := make(map[string]interface{})
		for k, v := range toSet {
			result[k] = v
		}
		for _, k := range toUnset {
			result[k] = nil
		}
		data, _ := json.Marshal(result)
		fmt.Println(string(data))
		return
	}

	var sb strings.Builder
	for k, v := range toSet {
		sb.WriteString(exportVar(shell, k, v))
	}
	for _, k := range toUnset {
		sb.WriteString(unsetVar(shell, k))
	}

	if sb.Len() > 0 {
		fmt.Print(sb.String())
	}
}

// outputUnload outputs commands to unload the current direnv environment
func outputUnload(shell string, currentEnv EnvMap, baseEnv EnvMap, prevDiff EnvDiff) {
	logStatus("unloading")

	// What to unset/restore: everything in prevDiff.Next
	// Restore to prevDiff.Prev values if they exist, otherwise unset

	toSet := make(EnvMap)
	var toUnset []string

	for k := range prevDiff.Next {
		if v, ok := prevDiff.Prev[k]; ok {
			// Restore previous value
			if cv, ok2 := currentEnv[k]; !ok2 || cv != v {
				toSet[k] = v
			}
		} else {
			// Unset
			if _, ok2 := currentEnv[k]; ok2 {
				toUnset = append(toUnset, k)
			}
		}
	}
	sort.Strings(toUnset)

	if len(toSet) == 0 && len(toUnset) == 0 {
		return
	}

	if shell == "json" {
		result := make(map[string]interface{})
		for k, v := range toSet {
			result[k] = v
		}
		for _, k := range toUnset {
			result[k] = nil
		}
		data, _ := json.MarshalIndent(result, "", "  ")
		fmt.Println(string(data))
		return
	}

	if shell == "gzenv" {
		// For gzenv unload, return empty or base env
		encoded, _ := gzenvEncode(EnvMap{})
		fmt.Println(encoded)
		return
	}

	if shell == "murex" || shell == "elvish" {
		result := make(map[string]interface{})
		for k, v := range toSet {
			result[k] = v
		}
		for _, k := range toUnset {
			result[k] = nil
		}
		data, _ := json.Marshal(result)
		fmt.Println(string(data))
		return
	}

	var sb strings.Builder
	for k, v := range toSet {
		sb.WriteString(exportVar(shell, k, v))
	}
	for _, k := range toUnset {
		sb.WriteString(unsetVar(shell, k))
	}

	if sb.Len() > 0 {
		fmt.Print(sb.String())
	}
}

func logExportedVars(baseEnv, newEnv EnvMap) {
	var added, changed, removed []string

	for k := range newEnv {
		if k == "DIRENV_DIFF" || k == "DIRENV_DIR" || k == "DIRENV_FILE" || k == "DIRENV_WATCHES" || varsToIgnore[k] {
			continue
		}
		if _, ok := baseEnv[k]; !ok {
			added = append(added, k)
		} else if baseEnv[k] != newEnv[k] {
			changed = append(changed, k)
		}
	}

	if len(added) > 0 || len(changed) > 0 || len(removed) > 0 {
		sort.Strings(added)
		sort.Strings(changed)
		sort.Strings(removed)

		var parts []string
		for _, k := range added {
			parts = append(parts, "+"+k)
		}
		for _, k := range changed {
			parts = append(parts, "~"+k)
		}
		for _, k := range removed {
			parts = append(parts, "-"+k)
		}

		logStatus("export %s", strings.Join(parts, " "))
	}
}

func isSubdirOrEqual(path, dir string) bool {
	if path == dir {
		return true
	}
	if strings.HasPrefix(path, dir+"/") {
		return true
	}
	return false
}

func keysOf(m EnvMap) []string {
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	return keys
}
