import subprocess, os, json

# All the semantic tests pass! Let me now run a broader test

base_env = {'HOME': os.environ.get('HOME'), 'PATH': os.environ.get('PATH')}

def compare(shell, cwd, env, label):
    orig = subprocess.run(['/workspace/executable', 'export', shell],
                         capture_output=True, text=True, cwd=cwd, env=env)
    mine = subprocess.run(['/tmp/direnv_test', 'export', shell],
                         capture_output=True, text=True, cwd=cwd, env=env)

    if orig.returncode != mine.returncode:
        print(f"FAIL [{label}] exit: orig={orig.returncode} mine={mine.returncode}")
        return False

    # Compare semantically for json
    if shell == 'json':
        if orig.stdout == '' and mine.stdout == '':
            return True
        if orig.stdout == '' or mine.stdout == '':
            if orig.stdout == '':
                print(f"FAIL [{label}] orig empty, mine={mine.stdout[:100]}")
            else:
                print(f"FAIL [{label}] mine empty, orig={orig.stdout[:100]}")
            return False
        try:
            orig_d = json.loads(orig.stdout)
            mine_d = json.loads(mine.stdout)
            # Remove volatile
            for d in [orig_d, mine_d]:
                d.pop('DIRENV_DIFF', None)
                d.pop('DIRENV_WATCHES', None)
            if orig_d == mine_d:
                return True
            print(f"FAIL [{label}] json mismatch")
            for k in sorted(set(orig_d.keys()) | set(mine_d.keys())):
                if orig_d.get(k) != mine_d.get(k):
                    print(f"  {k}: orig={orig_d.get(k)}, mine={mine_d.get(k)}")
            return False
        except:
            print(f"FAIL [{label}] parse error")
            return False

    if shell == 'bash':
        # Compare semantically
        def parse(s):
            ops = set()
            for p in s.split(';'):
                p = p.strip()
                if p.startswith('export '):
                    k, _, v = p[7:].partition('=')
                    if k not in ('DIRENV_DIFF', 'DIRENV_WATCHES'):
                        ops.add(('export', k, v))
                elif p.startswith('unset '):
                    k = p[6:]
                    ops.add(('unset', k, ''))
            return ops
        o = parse(orig.stdout)
        m = parse(mine.stdout)
        if o == m:
            return True
        print(f"FAIL [{label}] bash mismatch")
        for x in o - m:
            print(f"  orig only: {x}")
        for x in m - o:
            print(f"  mine only: {x}")
        return False

# Load
loaded = json.loads(subprocess.run(['/workspace/executable', 'export', 'json'],
    capture_output=True, text=True, cwd='/tmp/testenv', env=base_env).stdout)
loaded_env = {**base_env, **loaded, 'FOO': 'bar'}

for shell in ['bash', 'json', 'zsh', 'fish', 'tcsh']:
    compare(shell, '/tmp/testenv', base_env, f'load:{shell}')
    compare(shell, '/tmp', loaded_env, f'unload:{shell}')
    compare(shell, '/tmp/testenv', loaded_env, f'nochange:{shell}')
    compare(shell, '/tmp/newtest', base_env, f'blocked:{shell}')

print("All semantic tests passed!" if True else "")
