python3 << 'PYEOF'
import subprocess, os, json, base64, zlib

base_env = {'HOME': os.environ.get('HOME'), 'PATH': os.environ.get('PATH')}

def compare_gzenv(cwd, env, label):
    orig = subprocess.run(['/workspace/executable', 'export', 'gzenv'],
                         capture_output=True, text=True, cwd=cwd, env=env)
    mine = subprocess.run(['/tmp/direnv_test', 'export', 'gzenv'],
                         capture_output=True, text=True, cwd=cwd, env=env)

    if orig.returncode != mine.returncode:
        print(f"FAIL {label}: exit orig={orig.returncode} mine={mine.returncode}")
        return

    def decode(s):
        s = s.strip()
        if not s:
            return {}
        b = base64.urlsafe_b64decode(s + '==')
        dec = zlib.decompress(b)
        return json.loads(dec)

    orig_d = decode(orig.stdout)
    mine_d = decode(mine.stdout)

    # Remove volatile
    for d in [orig_d, mine_d]:
        if isinstance(d, dict):
            d.pop('DIRENV_DIFF', None)
            d.pop('DIRENV_WATCHES', None)

    if orig_d == mine_d:
        print(f"PASS {label}")
    else:
        print(f"FAIL {label}:")
        print(f"  orig: {orig_d}")
        print(f"  mine: {mine_d}")

# Test
result = subprocess.run(['/workspace/executable', 'export', 'json'],
                       capture_output=True, text=True, cwd='/tmp/testenv', env=base_env)
loaded = json.loads(result.stdout)
loaded_env = {**base_env, **loaded, 'FOO': 'bar'}

compare_gzenv('/tmp/testenv', base_env, 'gzenv load')
compare_gzenv('/tmp', loaded_env, 'gzenv unload')
