import subprocess, os, json, re

base_env = {'HOME': os.environ.get('HOME'), 'PATH': os.environ.get('PATH')}

def compare_semantic(shell, cwd, env, label):
    orig = subprocess.run(['/workspace/executable', 'export', shell],
                         capture_output=True, text=True, cwd=cwd, env=env)
    mine = subprocess.run(['/tmp/direnv_test', 'export', shell],
                         capture_output=True, text=True, cwd=cwd, env=env)

    if orig.returncode != mine.returncode:
        print(f"FAIL {label}: exit orig={orig.returncode} mine={mine.returncode}")
        return

    if shell == 'pwsh':
        # For pwsh, compare semantically (removing order differences)
        def parse_pwsh(s):
            ops = set()
            for op in s.split(';'):
                op = op.strip()
                if op.startswith('${env:'):
                    m = re.match(r"\$\{env:(\w+)\}='(.*?)'", op, re.DOTALL)
                    if m:
                        k, v = m.groups()
                        if k not in ('DIRENV_DIFF', 'DIRENV_WATCHES'):
                            ops.add(('set', k, v))
                elif op.startswith("Remove-Item"):
                    m = re.search(r"env:/(\w+)", op)
                    if m:
                        k = m.group(1)
                        ops.add(('unset', k, ''))
            return ops

        o = parse_pwsh(orig.stdout)
        m = parse_pwsh(mine.stdout)
        if o == m:
            print(f"PASS {label}")
        else:
            print(f"FAIL {label}:")
            print(f"  orig-only: {o - m}")
            print(f"  mine-only: {m - o}")
    elif shell == 'vim':
        # Compare vim semantically
        def parse_vim(s):
            ops = set()
            for line in s.strip().split('\n'):
                line = line.strip()
                if line.startswith("call setenv("):
                    m = re.match(r"call setenv\('([^']+)',(.*)\)", line)
                    if m:
                        k, v = m.groups()
                        if k not in ('DIRENV_DIFF', 'DIRENV_WATCHES'):
                            ops.add((k, v.strip("'")))
            return ops

        o = parse_vim(orig.stdout)
        m = parse_vim(mine.stdout)
        if o == m:
            print(f"PASS {label}")
        else:
            print(f"FAIL {label}:")
            print(f"  orig-only: {o - m}")
            print(f"  mine-only: {m - o}")
    else:
        if orig.stdout == mine.stdout:
            print(f"PASS {label}")
        else:
            print(f"DIFF {label}:")
            print(f"  orig: {orig.stdout[:100]}")
            print(f"  mine: {mine.stdout[:100]}")

result = subprocess.run(['/workspace/executable', 'export', 'json'],
                       capture_output=True, text=True, cwd='/tmp/testenv', env=base_env)
loaded = json.loads(result.stdout)
loaded_env = {**base_env, **loaded, 'FOO': 'bar'}

