import subprocess, os, json

print("=== Final Comparison Tests ===\n")

base_env = {'HOME': os.environ.get('HOME'), 'PATH': os.environ.get('PATH')}
orig = '/tmp/original_executable'
mine = '/workspace/executable'

passed = 0
failed = 0

def test_cmd(label, args, cwd=None, env=None, compare='exact', ignore_keys=None):
    global passed, failed

    kw = {'capture_output': True, 'text': True}
    if cwd:
        kw['cwd'] = cwd
    if env:
        kw['env'] = env

    o = subprocess.run([orig] + args, **kw)
    m = subprocess.run([mine] + args, **kw)

    if o.returncode != m.returncode:
        print(f"FAIL {label}: exit orig={o.returncode} mine={m.returncode}")
        failed += 1
        return

    if compare == 'exact':
        if o.stdout == m.stdout:
            print(f"PASS {label}")
            passed += 1
        else:
            print(f"FAIL {label}: stdout differs")
            print(f"  orig: {repr(o.stdout[:100])}")
            print(f"  mine: {repr(m.stdout[:100])}")
            failed += 1
    elif compare == 'json_semantic':
        try:
            od = json.loads(o.stdout) if o.stdout else {}
            md = json.loads(m.stdout) if m.stdout else {}
            if ignore_keys:
                for k in ignore_keys:
                    od.pop(k, None)
                    md.pop(k, None)
            if od == md:
                print(f"PASS {label}")
                passed += 1
            else:
                print(f"FAIL {label}: json differs")
                failed += 1
        except:
            print(f"FAIL {label}: json parse error")
            failed += 1

# Basic commands
test_cmd("version", ['version'])
test_cmd("version 2.37.1", ['version', '2.37.1'])
test_cmd("version 2.38.0", ['version', '2.38.0'])
test_cmd("help", ['help'])
test_cmd("stdlib (count)", ['stdlib'], compare='exact')  # Should match exactly

# Export commands (with env -i)
clean_env = {'HOME': os.environ.get('HOME'), 'PATH': os.environ.get('PATH')}

for shell in ['bash', 'zsh', 'fish', 'tcsh', 'json', 'murex', 'elvish', 'gzenv', 'pwsh', 'vim', 'gha', 'systemd']:
    result = subprocess.run([orig, 'export', shell],
                           capture_output=True, text=True,
                           cwd='/tmp/testenv', env=clean_env)
    mine_result = subprocess.run([mine, 'export', shell],
                                capture_output=True, text=True,
                                cwd='/tmp/testenv', env=clean_env)

    if result.returncode != mine_result.returncode:
        print(f"FAIL export {shell}: exit codes differ")
        failed += 1
    else:
        print(f"PASS export {shell} (exit code)")
        passed += 1

print(f"\n=== Total: {passed} passed, {failed} failed ===")
